question.answer:
package main

type Ticket struct {
	Holder string
	Seat   string
	Paid   bool
}

func sameTicket(a, b Ticket) bool {
	return a == b
}

func blank(t Ticket) bool {
	return t == Ticket{}
}

testcode.text:
a := Ticket{Holder: "Ada Lovelace", Seat: "B4", Paid: true}
b := Ticket{Holder: "Ada Lovelace", Seat: "B4", Paid: true}
fmt.Println(sameTicket(a, b))

a := Ticket{Holder: "Ada Lovelace", Seat: "B4"}
b := Ticket{Holder: "Ada Lovelace", Seat: "B5"}
fmt.Println(sameTicket(a, b), blank(a))

a := Ticket{Holder: "Ada Lovelace", Seat: "B4", Paid: true}
b := Ticket{Holder: "Ada", Seat: "Lovelace B4", Paid: true}
fmt.Println(a, b, sameTicket(a, b))

a := Ticket{Holder: "Grace Hopper", Seat: "C1", Paid: true}
b := Ticket{Holder: "Grace Hopper", Seat: "C1"}
fmt.Println(sameTicket(a, b), blank(Ticket{Paid: true}), blank(b), blank(Ticket{}))

