question.answer:
package main

import (
	"fmt"
	"strings"
)

type Product struct {
	Name  string
	Unit  string
	Aisle int
}

var unitNames = strings.NewReplacer("mm", " millimetre", "m", " metre", "kg", " kilogram", "g", " gram")

func newProduct(name, unit string, aisle int) Product {
	if unit == "" {
		unit = "each"
	}
	return Product{
		Name:  unitNames.Replace(strings.TrimSpace(name)),
		Unit:  unit,
		Aisle: aisle,
	}
}

func describe(p Product) string {
	sold := "sold by the " + p.Unit
	if p.Unit == "each" {
		sold = "sold singly"
	}
	where := fmt.Sprintf("aisle %d", p.Aisle)
	if p.Aisle == 0 {
		where = "not yet shelved"
	}
	return p.Name + ", " + sold + ", " + where
}
